code_examples.safe:
InputStream in = null;
OutputStream out = null;
try {
    in = new FileInputStream(inputFile);
    out = new FileOutputStream(outputFile);
    ...
    FileCopyUtils.copy(fis, os);
} catch (IOException e) {
    logger.error(e);
// 항상 수행되는 finally 블록에서 할당받은 모든 자원에 대해 각각 null검사를 수행 후 예외처리를 하여 자원을 해제하여야 한다.
} finally {
    if (in != null) {
        try {
            in.close();
        } catch (IOException e) {
            logger.error(e);
        }
    }
    if (out != null) {
        try {
            out.close();
        } catch (IOException e) {
            logger.error(e);
        }
    }
}

